+fn mul_wide(a: [u64; 4], b: [u64; 4]) -> [u64; 8] {
+    // Product scanning: column k sums every a[i] * b[k - i] into a 192-bit
+    // accumulator (acc, top) before emitting its low word.
+    let p = |i: usize, j: usize| (a[i] as u128) * (b[j] as u128);
+    let mut w = [0u64; 8];
+    let mut acc = 0u128;
+
+    for (k, out) in w.iter_mut().enumerate().take(7) {
+        let mut top = 0u64;
+        let lo = k.saturating_sub(3);
+        let hi = if k < 3 { k } else { 3 };
+        for i in lo..=hi {
+            let (sum, overflow) = acc.overflowing_add(p(i, k - i));
+            acc = sum;
+            top += u64::from(overflow);
+        }
+        *out = acc as u64;
+        acc = (acc >> 64) | ((top as u128) << 64);
+    }
+    w[7] = acc as u64;
+
+    w
+}

